solution:
#include <stdio.h>
long long giai_thua(int n) { return n <= 1 ? 1 : n * giai_thua(n - 1); }
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    printf("%lld\n", giai_thua(n));
    return 0;
}
